"/* ==========================================================================
   Model Viewer Demo - Stiller
   Sadece sistem fontları kullanılmıştır. Harici tasarım bağımlılığı yoktur.
   ========================================================================== */

/* Temel Reset ve Değişkenler */
:root {
  --bg-color: #0f172a;
  --card-bg: rgba(30, 41, 59, 0.7);
  --card-border: rgba(255, 255, 255, 0.1);
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --accent-color: #0ea5e9;
  --accent-hover: #0284c7;
  --success-color: #10b981;
  --warning-color: #f59e0b;
  --error-color: #ef4444;
  --font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  --radius-lg: 16px;
  --radius-md: 8px;
  --shadow-main: 0 20px 25px -5px rgba(0, 0, 0, 0.4), 0 8px 10px -6px rgba(0, 0, 0, 0.3);
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-color);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
  overflow-x: hidden; /* Mobil yatay taşma engelleme */
  line-height: 1.5;
}

/* Ana Konteyner */
.app-container {
  width: 100%;
  max-width: 960px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* Başlık */
.app-header {
  text-align: center;
}

.app-header h1 {
  font-size: clamp(1.4rem, 4vw, 2.2rem);
  font-weight: 700;
  color: #ffffff;
  letter-spacing: -0.02em;
}

.app-header .subtitle {
  color: var(--text-muted);
  font-size: clamp(0.875rem, 2vw, 1rem);
  margin-top: 6px;
}

